# Several matchers on one label
http_requests_total{status=~"5..", status!="503"}

# Several metrics at once via __name__
{__name__=~"node_(cpu|memory).*", instance="web1:9100"}

# Series that lack a label / have the label
up{env=""}
up{env=~".+"}

# Anchored regex: prefix needs .*
http_requests_total{path=~"/api/v1/.*", method=~"GET|HEAD"}

# Prometheus 3.x quoted UTF-8 names (OpenTelemetry style)
{"http.server.request.count", "service.name"="checkout"}

package main

import (
	"net/http"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

var (
	reqs = promauto.NewCounterVec(prometheus.CounterOpts{
		Name: "shop_http_requests_total", Help: "HTTP requests handled.",
	}, []string{"route", "method", "code"})
	dur = promauto.NewHistogramVec(prometheus.HistogramOpts{
		Name: "shop_http_request_duration_seconds", Help: "Request latency.",
		Buckets: []float64{0.05, 0.1, 0.25, 0.5, 1, 2.5},
	}, []string{"route", "method", "code"})
)

func instrument(route string, h http.Handler) http.Handler {
	l := prometheus.Labels{"route": route}
	return promhttp.InstrumentHandlerDuration(dur.MustCurryWith(l),
		promhttp.InstrumentHandlerCounter(reqs.MustCurryWith(l), h))
}

func main() {
	http.Handle("/orders", instrument("/orders", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})))
	http.Handle("/metrics", promhttp.Handler()) // go_* and process_* come for free
	http.ListenAndServe(":8080", nil)
}
// curl -s localhost:8080/metrics | grep shop_http_requests_total
// shop_http_requests_total{code="200",method="get",route="/orders"} 3

// client_golang: one histogram, native plus classic buckets for migration
dur := promauto.NewHistogramVec(prometheus.HistogramOpts{
	Name:                            "shop_http_request_duration_seconds",
	Help:                            "Request latency.",
	Buckets:                         []float64{0.05, 0.1, 0.25, 0.5, 1}, // classic (optional)
	NativeHistogramBucketFactor:     1.1,     // ~schema 3
	NativeHistogramMaxBucketNumber:  160,
	NativeHistogramMinResetDuration: time.Hour,
}, []string{"route"})
dur.WithLabelValues("/orders").Observe(0.123)

